    next_grid = grid.copy()

    # Iterate over all possible 2x2 top-left corners
    for i in range(N - 1):
        for j in range(N - 1):
            # The 2x2 block is defined by indices (i, j), (i+1, j), (i, j+1), (i+1, j+1)

            block = [
                current_grid[i, j], current_grid[i+1, j], 
                current_grid[i, j+1], current_grid[i+1, j+1]
            ]

            S = sum(block)

            # Rule 1: Growth (S=3)
            if S == 3:
                # Find the sterile cell (0)
                sterile_indices = [k for k, val in enumerate(block) if val == 0]

                # There should be exactly one sterile cell
