                    r_0 = (k_0 // 2) + i
                    c_0 = (k_0 % 2) + j

                    # This cell gets infected
                    next_grid[r_0, c_0] = 1

            # Rule 2: Mutation (S=2)
            elif S == 2:
                # All four cells flip state

                coords = [
