def create_corner_grid(k, N):
    """Creates an initial grid by filling the top-left corner with k infected cells."""
    grid = np.zeros((N, N), dtype=int)
    count = 0
    for r in range(N):
        for c in range(N):
            if count < k:
                grid[r, c] = 1
                count += 1
            else:
                # Optimization: break early if we exceed k, since we are filling row by row
                break 
        if count >= k:
            break
    return grid

